"""Local MCP demo server: no account or external service needed."""

try:
    from mcp.server.mcpserver import MCPServer
except ImportError:  # MCP 1.x
    from mcp.server.fastmcp import FastMCP as MCPServer

server = MCPServer("Orders")


@server.tool()
def lookup_order(order_id: str) -> dict:
    """Look up a demo order's payment status and total."""
    return {"order_id": order_id, "total_usd": 12, "status": "paid"}


if __name__ == "__main__":
    server.run()

"""Real MCP tool with a separately excluded tool for portability acceptance."""

try:
    from mcp.server.mcpserver import MCPServer as FastMCP
except ImportError:
    from mcp.server.fastmcp import FastMCP

server = FastMCP("portable")


@server.tool()
def slow() -> str:
    """Validate the previously looked-up order."""
    return "Validated USD 12"


@server.tool()
def forbidden() -> str:
    """Must never be offered to the model."""
    raise AssertionError("The MCP allowlist was not enforced")


if __name__ == "__main__":
    server.run()

import asyncio

import pytest

from liteagents import LiteAgentClient, LiteAgentOptions, ProfileOptions
from tests.test_python_harnesses import Lookup, deep_model, pydantic_model


def parent_model(harness):
    pytest.importorskip("deepagents" if harness == "deepagents" else "pydantic_ai")
    if harness == "deepagents":
        from langchain_core.messages import AIMessage, ToolMessage
        from langchain_core.outputs import ChatGeneration, ChatResult

        class Parent(type(deep_model())):
            def bind_tools(self, tools, **kwargs):
                assert {t.name for t in tools} == {"read_file", "delegate_auditor"}
                return self

            def _generate(self, messages, stop=None, run_manager=None, **kwargs):
                returned = next((m for m in messages if isinstance(m, ToolMessage)), None)
                reply = (
                    AIMessage(content=returned.content)
                    if returned
                    else AIMessage(
                        content="",
                        tool_calls=[
                            {
                                "id": "call1",
                                "name": "delegate_auditor",
                                "args": {"prompt": "Look up A123"},
                            }
                        ],
                    )
                )
                return ChatResult(generations=[ChatGeneration(message=reply)])

        return Parent()
    from pydantic_ai.messages import ModelResponse, TextPart, ToolCallPart, ToolReturnPart
    from pydantic_ai.models.function import FunctionModel

    def respond(messages, info):
        assert {t.name for t in info.function_tools} == {"read_file", "delegate_auditor"}
        returned = next(
            (p for m in messages for p in m.parts if isinstance(p, ToolReturnPart)), None
        )
        return ModelResponse(
            parts=[TextPart(returned.content)]
            if returned
            else [ToolCallPart("delegate_auditor", {"prompt": "Look up A123"}, "call1")]
        )

    return FunctionModel(respond)


@pytest.mark.parametrize(
    "harness,child", [("deepagents", deep_model), ("pydantic-ai", pydantic_model)]
)
async def test_named_child_model_tools_attribution_and_journal_scope(harness, child, tmp_path):
    tool = Lookup()
    profile = ProfileOptions(
        harness=harness,
        model="scripted/parent",
        tools=["read_file"],
        subagents={
            "auditor": {
                "description": "Audit an order",
                "model": "scripted/child",
                "tools": ["lookup"],
            }
        },
        harness_options={
            "model_instance": parent_model(harness),
            "subagent_model_instances": {"auditor": child()},
        },
    )
    async with LiteAgentClient(
        options=LiteAgentOptions(profile=profile, tools=[tool], cwd=tmp_path)
    ) as client:
        run = await client.start_run("Delegate the order audit")
        assert (await asyncio.wait_for(run.result(), 5)).text == "Order total: USD 12"
        assert len(tool.calls) == 1
        events = [e async for e in run.events()]
        started = next(e for e in events if e.kind == "subagent_started")
        assert started.data["agent"] == "auditor"
        assert started.data["model"] == "scripted/child"
        assert started.data["scope"] == "root/tool:call1"
        assert any(e.kind == "subagent_completed" for e in events)
        assert any(k.startswith("result:root/tool:call1:tool:call1") for k in run.control.values)

import asyncio
import io
import socket
import sys
from contextlib import AsyncExitStack

import pytest

from liteagents import LiteAgentClient, LiteAgentOptions, ProfileOptions
from liteagents.runtime.tooling import load_servers
from tests.test_mcp_transport import SERVER


async def test_stdio_mcp_with_notebook_style_stderr(monkeypatch):
    pytest.importorskip("mcp")
    monkeypatch.setattr(sys, "stderr", io.StringIO())
    profile = ProfileOptions(
        harness="deepagents", model="scripted/test",
        mcp_servers={"evidence": {"command": sys.executable, "args": [str(SERVER)],
                                  "allowed_tools": ["read_memory"]}},
    )
    async with AsyncExitStack() as stack:
        tools = await load_servers(profile, stack)
        assert "evidence:notebook" in str(await tools[0].execute({"query": "notebook"}))


@pytest.mark.integration
@pytest.mark.parametrize("transport", ["stdio", "http", "sse"])
async def test_profile_manages_real_mcp_connection(transport):
    pytest.importorskip("mcp")
    process = None
    config = {"command": sys.executable, "args": [str(SERVER)], "allowed_tools": ["read_memory"]}
    if transport != "stdio":
        with socket.socket() as sock:
            sock.bind(("127.0.0.1", 0))
            port = sock.getsockname()[1]
        process = await asyncio.create_subprocess_exec(
            sys.executable,
            str(SERVER),
            str(port),
            "sse" if transport == "sse" else "streamable-http",
            stdout=asyncio.subprocess.DEVNULL,
            stderr=asyncio.subprocess.DEVNULL,
        )
        async with asyncio.timeout(10):
            while True:
                try:
                    _, writer = await asyncio.open_connection("127.0.0.1", port)
                    writer.close()
                    await writer.wait_closed()
                    break
                except OSError:
                    await asyncio.sleep(0.05)
        config = {
            "url": f"http://127.0.0.1:{port}/" + ("sse" if transport == "sse" else "mcp"),
            "transport": transport,
            "headers": {"Authorization": "Bearer synthetic"},
            "allowed_tools": ["read_memory"],
        }
    try:
        profile = ProfileOptions(
            harness="deepagents", model="scripted/test", mcp_servers={"evidence": config}
        )
        async with AsyncExitStack() as stack:
            tools = await load_servers(profile, stack)
            assert [t.name for t in tools] == ["evidence_read_memory"]
            assert "evidence:hello" in str(await tools[0].execute({"query": "hello"}))
    finally:
        if process is not None:
            process.terminate()
            try:
                await asyncio.wait_for(process.wait(), 5)
            except TimeoutError:
                process.kill()
                await process.wait()


@pytest.mark.integration
@pytest.mark.parametrize("harness", ["deepagents", "pydantic-ai"])
async def test_native_python_loop_executes_profile_mcp(harness, tmp_path):
    pytest.importorskip("mcp")
    if harness == "deepagents":
        pytest.importorskip("deepagents")
        from langchain_core.language_models.chat_models import BaseChatModel
        from langchain_core.messages import AIMessage, ToolMessage
        from langchain_core.outputs import ChatGeneration, ChatResult

        class Model(BaseChatModel):
            @property
            def _llm_type(self):
                return "mcp-test"

            def bind_tools(self, tools, **kwargs):
                assert [t.name for t in tools] == ["evidence_read_memory"]
                return self

            def _generate(self, messages, stop=None, run_manager=None, **kwargs):
                result = next((m for m in messages if isinstance(m, ToolMessage)), None)
                message = (
                    AIMessage(content=str(result.content))
                    if result
                    else AIMessage(
                        content="",
                        tool_calls=[
                            {
                                "id": "m1",
                                "name": "evidence_read_memory",
                                "args": {"query": "verified"},
                            }
                        ],
                    )
                )
                return ChatResult(generations=[ChatGeneration(message=message)])

        model = Model()
    else:
        pytest.importorskip("pydantic_ai")
        from pydantic_ai.messages import ModelResponse, TextPart, ToolCallPart, ToolReturnPart
        from pydantic_ai.models.function import FunctionModel

        def respond(messages, info):
            result = next(
                (p for m in messages for p in m.parts if isinstance(p, ToolReturnPart)), None
            )
            return ModelResponse(
                parts=[TextPart(str(result.content))]
                if result
                else [ToolCallPart("evidence_read_memory", {"query": "verified"}, "m1")]
            )

        model = FunctionModel(respond)
    profile = ProfileOptions(
        harness=harness,
        model="scripted/test",
        tools=["evidence_read_memory"],
        mcp_servers={
            "evidence": {
                "command": sys.executable,
                "args": [str(SERVER)],
                "allowed_tools": ["read_memory"],
            }
        },
        harness_options={"model_instance": model},
    )
    async with LiteAgentClient(options=LiteAgentOptions(profile=profile, cwd=tmp_path)) as client:
        _ = [e async for e in client.query("Find evidence", run_id="mcp")]
        assert "evidence:verified" in (await (await client.get_run("mcp")).result()).text

"""Exclusive ownership of a run, held for its full execution attempt."""

from __future__ import annotations

import hashlib
from contextlib import asynccontextmanager

from filelock import FileLock, Timeout

from ..errors import ConfigurationError
from .store import RunStore


@asynccontextmanager
async def own_run(store: RunStore, key: str):
    if store.db.postgres:
        import psycopg

        identifier = int.from_bytes(hashlib.sha256(key.encode()).digest()[:8], "big", signed=True)
        async with await psycopg.AsyncConnection.connect(
            store.db.url, autocommit=True
        ) as connection:
            cursor = await connection.execute("SELECT pg_try_advisory_lock(%s)", (identifier,))
            row = await cursor.fetchone()
            if row is None or not row[0]:
                raise ConfigurationError("Another worker owns this run")

            async def check():
                try:
                    await connection.execute("SELECT 1")
                except psycopg.OperationalError as exc:
                    raise ConnectionError("Run ownership connection was lost") from exc

            try:
                yield check
            finally:
                if not connection.closed:
                    await connection.execute("SELECT pg_advisory_unlock(%s)", (identifier,))
    else:
        lock = FileLock(
            str(store.db.path) + "." + hashlib.sha256(key.encode()).hexdigest()[:24] + ".lock"
        )
        try:
            lock.acquire(timeout=0)
        except Timeout as exc:
            raise ConfigurationError("Another worker owns this run") from exc

        async def check():
            if not lock.is_locked:
                raise ConfigurationError("Run ownership was lost")

        try:
            yield check
        finally:
            lock.release()
